"use strict";
function setFooterYear() {
const year = document.getElementById("year");
if (year) year.textContent = new Date().getFullYear();
}
function setupMobileMenu() {
const btn = document.getElementById("menuBtn");
const nav = document.getElementById("mobileNav");
const overlay = document.getElementById("menuOverlay");
if (!btn || !nav) return;
const setMenu = (open) => {
nav.classList.toggle("is-open", open);
overlay?.classList.toggle("is-open", open);
btn.classList.toggle("is-open", open);
btn.textContent = open ? "×" : "☰";
btn.setAttribute("aria-expanded", String(open));
nav.setAttribute("aria-hidden", String(!open));
if (open) {
  nav.removeAttribute("inert");
} else {
  nav.setAttribute("inert", "");
}

document.body.classList.toggle("menu-open", open);
};
btn.addEventListener("click", () => setMenu(!nav.classList.contains("is-open")));
overlay?.addEventListener("click", () => setMenu(false));
nav.querySelectorAll("a").forEach((a) => a.addEventListener("click", () => setMenu(false)));
document.addEventListener("keydown", (e) => { if (e.key === "Escape") setMenu(false); });
}
function setupSmartHeader() {
const onScroll = () => document.body.classList.toggle("scrolled", window.scrollY > 40);
onScroll();
window.addEventListener("scroll", onScroll, { passive: true });
}
function setupFloatingCtas() {
const hero = document.querySelector(".hero");
const getThreshold = () => hero ? hero.offsetTop + hero.offsetHeight * 0.10 : 160;
const onScroll = () => document.body.classList.toggle("hero-passed", window.scrollY > getThreshold());
onScroll();
window.addEventListener("scroll", onScroll, { passive: true });
window.addEventListener("resize", onScroll);
}
function setupHeroSlider() {
const slider = document.querySelector('[data-slider="hero"]');
if (!slider) return;
const slides = Array.from(slider.querySelectorAll(".slide"));
const dots = Array.from(slider.querySelectorAll(".dot"));
const prev = slider.querySelector(".slideNav--prev");
const next = slider.querySelector(".slideNav--next");
if (slides.length <= 1) return;
let current = Math.max(0, slides.findIndex((s) => s.classList.contains("is-active")));
let timer = null;
const goTo = (index) => {
current = (index + slides.length) % slides.length;
slides.forEach((slide, i) => slide.classList.toggle("is-active", i === current));
dots.forEach((dot, i) => dot.classList.toggle("is-active", i === current));
};
const stop = () => { if (timer) window.clearInterval(timer); };
const start = () => {
stop();
timer = window.setInterval(() => goTo(current + 1), 6500);
};
prev?.addEventListener("click", () => { goTo(current - 1); start(); });
next?.addEventListener("click", () => { goTo(current + 1); start(); });
dots.forEach((dot, i) => dot.addEventListener("click", () => { goTo(i); start(); }));
slider.addEventListener("mouseenter", stop);
slider.addEventListener("mouseleave", start);
let touchStartX = 0;
slider.addEventListener("touchstart", (e) => { touchStartX = e.touches[0].clientX; }, { passive: true });
slider.addEventListener("touchend", (e) => {
const diff = touchStartX - e.changedTouches[0].clientX;
if (Math.abs(diff) > 45) { goTo(current + (diff > 0 ? 1 : -1)); start(); }
}, { passive: true });
goTo(current);
window.addEventListener("load", () => {
  setTimeout(start, 2500);
});
}
function setupReviewExpand() {
document.querySelectorAll(".tCard").forEach((card) => {
const text = card.querySelector(".reviewText");
const btn = card.querySelector(".reviewMore");
if (!text || !btn) return;
requestAnimationFrame(() => {
const needsButton = text.scrollHeight > text.clientHeight + 3;
btn.hidden = !needsButton;
btn.style.display = needsButton ? "inline-flex" : "none";
});
btn.addEventListener("click", (e) => {
e.preventDefault();
card.classList.toggle("open");
btn.textContent = card.classList.contains("open") ? "Ver menos" : "Ver avaliação completa →";
});
});
}
function setupTestimonials() {
const slider = document.querySelector('[data-slider="testimonials"]');
if (!slider) return;
const track = slider.querySelector(".tTrack");
const cards = Array.from(slider.querySelectorAll(".tCard"));
const prev = slider.querySelector(".tNav--prev");
const next = slider.querySelector(".tNav--next");
const dotsWrap = slider.querySelector(".tDots");
if (!track || !cards.length) return;
if (dotsWrap) {
dotsWrap.innerHTML = cards.map((_, i) => `<button class="tDot${i === 0 ? " is-active" : ""}" aria-label="Depoimento ${i + 1}"></button>`).join("");
}
const dots = Array.from(slider.querySelectorAll(".tDot"));
let current = 0;
let timer = null;
const isMobile = () => window.matchMedia("(max-width: 680px)").matches;
const goTo = (index) => {
current = (index + cards.length) % cards.length;
cards.forEach((card, i) => card.classList.toggle("is-active", i === current));
dots.forEach((dot, i) => dot.classList.toggle("is-active", i === current));
if (isMobile()) track.style.transform = `translateX(-${current * 100}%)`;
else track.style.transform = "";
};
const stop = () => { if (timer) window.clearInterval(timer); };
const start = () => {
stop();
timer = window.setInterval(() => { if (isMobile()) goTo(current + 1); }, 4200);
};
prev?.addEventListener("click", () => { goTo(current - 1); start(); });
next?.addEventListener("click", () => { goTo(current + 1); start(); });
dots.forEach((dot, i) => dot.addEventListener("click", () => { goTo(i); start(); }));
let touchStartX = 0;
track.addEventListener("touchstart", (e) => { touchStartX = e.touches[0].clientX; stop(); }, { passive: true });
track.addEventListener("touchend", (e) => {
const diff = touchStartX - e.changedTouches[0].clientX;
if (Math.abs(diff) > 45) goTo(current + (diff > 0 ? 1 : -1));
start();
}, { passive: true });
slider.addEventListener("mouseenter", stop);
slider.addEventListener("mouseleave", start);
window.addEventListener("resize", () => goTo(current));
goTo(0);
start();
}
function setupReveal() {
const els = document.querySelectorAll(".reveal, .card, .actCard, .blogCard, .tCard, .trustItem");
if (!("IntersectionObserver" in window)) {
els.forEach((el) => el.classList.add("is-visible"));
return;
}
const io = new IntersectionObserver((entries) => {
entries.forEach((entry) => {
if (entry.isIntersecting) {
entry.target.classList.add("is-visible");
io.unobserve(entry.target);
}
});
}, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });
els.forEach((el) => { el.classList.add("reveal"); io.observe(el); });
}
function setupMap() {
  const mapEl = document.getElementById("map");
  if (!mapEl) return;

  let loaded = false;

  const loadLeafletAsset = (tagName, attrs) => new Promise((resolve, reject) => {
    const el = document.createElement(tagName);
    Object.entries(attrs).forEach(([key, value]) => el.setAttribute(key, value));
    el.onload = resolve;
    el.onerror = reject;
    document.head.appendChild(el);
  });

  const loadMap = async () => {
    if (loaded) return;
    loaded = true;

    if (!document.querySelector('link[data-leaflet-css]')) {
      await loadLeafletAsset("link", {
        rel: "stylesheet",
        href: "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css",
        "data-leaflet-css": "true"
      });
    }

    if (!window.L) {
      await loadLeafletAsset("script", {
        src: "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js",
        "data-leaflet-js": "true"
      });
    }

    const map = L.map(mapEl, {
      scrollWheelZoom: false
    }).setView([-3.741, -38.526], 12);

    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      maxZoom: 18,
      attribution: "© OpenStreetMap"
    }).addTo(map);

    const units = [
      { name: "Dentalli Fortaleza", coords: [-3.73186, -38.52667], bairro: "Fortaleza/CE" },
      { name: "Dentalli Aldeota", coords: [-3.73855, -38.49042], bairro: "Aldeota" },
      { name: "Dentalli Presidente Kennedy", coords: [-3.72780, -38.57060], bairro: "Presidente Kennedy" },
      { name: "Dentalli Dionísio Torres", coords: [-3.75210, -38.49760], bairro: "Dionísio Torres" },
      { name: "Dentalli Parangaba", coords: [-3.77687, -38.56704], bairro: "Parangaba" },
      { name: "Dentalli Montese", coords: [-3.76081, -38.55392], bairro: "Montese" },
      { name: "Dentalli Quintino Cunha", coords: [-3.75894, -38.60291], bairro: "Quintino Cunha" },
      { name: "Dentalli Cidade dos Funcionários", coords: [-3.79815, -38.49745], bairro: "Cidade dos Funcionários" },
      { name: "Dentalli Maraponga", coords: [-3.79918, -38.56847], bairro: "Maraponga" },
      { name: "Dentalli Messejana", coords: [-3.83353, -38.49483], bairro: "Messejana" },
      { name: "Dentalli Cajazeiras", coords: [-3.82483, -38.51562], bairro: "Cajazeiras" },
    ];

    units.forEach((unit) => {
      const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${unit.coords[0]},${unit.coords[1]}`;

      L.marker(unit.coords)
        .addTo(map)
        .bindPopup(`<strong>${unit.name}</strong><br>${unit.bairro}<br><a href="${mapsUrl}" target="_blank" rel="noopener">Traçar rota</a>`)
        .bindTooltip(unit.bairro);
    });
  };

  const observer = new IntersectionObserver((entries) => {
    if (entries[0].isIntersecting) {
      observer.disconnect();
      loadMap().catch(() => {
        mapEl.innerHTML = "<p style='color:#111;padding:20px;text-align:center'>Não foi possível carregar o mapa agora.</p>";
      });
    }
  }, {
    rootMargin: "300px"
  });

  observer.observe(mapEl);
}
// Dropdown Tratamentos no menu mobile
function setupMobileTratamentos() {

  const button = document.querySelector(".mobileNav__title");
  const group = document.querySelector(".mobileNav__group");

  if (!button || !group) return;


  button.addEventListener("click", () => {

    group.classList.toggle("active");

  });

}

// Popup de benefício/cupom da home (mesmo padrão de setupPromoPopup das outras páginas)
function setupPromoPopup() {
  const overlay = document.getElementById("benefitOverlay");
  const closeBtn = document.getElementById("benefitClose");
  const noBtn = document.getElementById("benefitNo");
  const gift = document.getElementById("benefitGift");
  const reveal = document.getElementById("benefitReveal");
  const codeEl = document.getElementById("benefitCode");
  const timerEl = document.getElementById("benefitTimer");
  const whatsapp = document.getElementById("popupHome");

  if (!overlay || !gift || !reveal || !codeEl || !timerEl || !whatsapp) return;

  const KEY_CLOSED = "dentalli_benefit_closed_until";
  const KEY_REDEEMED = "dentalli_benefit_redeemed_until";
  const KEY_CODE = "dentalli_benefit_code";
  const KEY_END = "dentalli_benefit_timer_end";

  const now = Date.now();
  const blockedUntil = Math.max(
    Number(localStorage.getItem(KEY_CLOSED) || 0),
    Number(localStorage.getItem(KEY_REDEEMED) || 0)
  );

  if (blockedUntil > now) return;

  let opened = false;

  let code = localStorage.getItem(KEY_CODE);
  if (!code) {
    code = "DTL-" + Math.floor(10000 + Math.random() * 89999);
    localStorage.setItem(KEY_CODE, code);
  }

  codeEl.textContent = code;

  let timerEnd = Number(localStorage.getItem(KEY_END) || 0);
  if (!timerEnd || timerEnd < now) {
    timerEnd = now + 5 * 60 * 1000;
    localStorage.setItem(KEY_END, String(timerEnd));
  }

  const updateTimer = () => {
    const diff = Math.max(0, timerEnd - Date.now());
    const min = String(Math.floor(diff / 60000)).padStart(2, "0");
    const sec = String(Math.floor((diff % 60000) / 1000)).padStart(2, "0");
    timerEl.textContent = `${min}:${sec}`;
  };

  updateTimer();
  setInterval(updateTimer, 1000);

  const openPopup = () => {
    if (opened) return;
    opened = true;
    overlay.classList.add("is-open");
    overlay.setAttribute("aria-hidden", "false");
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({ event: "popup_view" });
  };

  const closePopup = (days = 30) => {
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");

    localStorage.setItem(
      KEY_CLOSED,
      String(Date.now() + days * 24 * 60 * 60 * 1000)
    );
  };

  const revealGift = () => {
    gift.style.display = "none";

    reveal.hidden = false;
    reveal.removeAttribute("hidden");
    reveal.style.display = "block";

    whatsapp.dataset.codigo = code;
    whatsapp.href = window.buildWhatsAppUrl(whatsapp.dataset.waContext, { codigo: code });
  };

  gift.addEventListener("click", (e) => {
    e.preventDefault();
    revealGift();
  });

  closeBtn?.addEventListener("click", () => closePopup(7));
  noBtn?.addEventListener("click", () => closePopup(30));

  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) {
      closePopup(7);
    }
  });

  whatsapp.addEventListener("click", () => {
    localStorage.setItem(KEY_REDEEMED, String(Date.now() + 30 * 24 * 60 * 60 * 1000));
  });

  // Exit intent mobile - botão voltar
  if (/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
    const lockBackButton = () => {
      history.pushState({ benefitPopup: true }, "", location.href);
    };

    setTimeout(lockBackButton, 800);

    window.addEventListener("popstate", () => {
      if (!overlay.classList.contains("is-open")) {
        openPopup();

        setTimeout(() => {
          history.pushState({ benefitPopup: true }, "", location.href);
        }, 100);
      }
    });
  }

  setTimeout(() => {
    document.addEventListener("mouseleave", (e) => {
      if (e.clientY <= 0) openPopup();
    });
  }, 2000);

  setTimeout(openPopup, 15000);

  document.addEventListener(
    "scroll",
    () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight;
      if (scrollable > 0 && window.scrollY / scrollable >= 0.6) openPopup();
    },
    { passive: true }
  );
}

document.addEventListener("DOMContentLoaded", () => {
  setFooterYear();
  setupMobileMenu();
  setupSmartHeader();
  setupFloatingCtas();
  setupHeroSlider();
  setupTestimonials();
  setupReviewExpand();
  setupReveal();
  setupMap();
   setupMobileTratamentos();
  // setupPromoPopup(); // Popup desativado a pedido da clínica

  const doctorCard = document.querySelector(".doctorMiniCard");
  if (doctorCard) {
    setTimeout(() => doctorCard.classList.add("is-visible"), 450);
  }
});